/**
 * Where a catalog comes from.
 *
 * `read` answers with the catalog in the type's own format, or fails with the reason, which the Store shows beside the last good
 * catalog it keeps. It runs whenever the catalog is refreshed, so it is as slow as its source.
 *
 * A source that runs a program or reads a file does it through the `spawner` `read` is handed, which is the host's and has the
 * person's own reach: `spawn` starts a program as the person, and `read_file` reads a file anywhere the person's account can, by
 * its absolute path (`write_file` and `remove_file` are refused). A script has no other way to do either. The source destroys it,
 * even when it refuses.
 */
export const CatalogSource = described["catalog_source"];

/**
 * Starts programs where the host chooses: on this machine, on another over SSH, in a container or
 * a virtual machine. The host implements it and hands one to every
 * [`AcpHarness::start`](crate::AcpHarness::start); the provider owns it from then on, starts its
 * programs through it, or never calls it, and destroys it by the time it calls the sink's
 * `closed`.
 *
 * Every slot takes `&self`, so a provider may call it from several threads at once.
 */
export const ProcessSpawner = described["process_spawner"];

/**
 * One program a spawner started, and everything it starts in turn.
 *
 * Every slot takes `&self`, so one thread may write or kill while another waits in `read`.
 * Destroying it kills the whole tree, as [`kill`](Self::kill) does.
 */
export const SpawnedProcess = described["spawned_process"];

/**
 * The models of a Store type, and what the person does with each.
 *
 * Every method is required and synchronous, and every object a method is handed is the provider's to destroy. A provider with no
 * settings refuses `keep`, and one with no speech service refuses `service`, `UNSUPPORTED` with
 * its reason; the host asks neither unless `describe` offers it.
 */
export const ModelStore = described["model_store"];

/**
 * A kind of tab.
 *
 * `describe` answers the same on every call with nothing run. `tail` is asked only of a [`Shows::Log`] kind.
 */
export const PanelTab = described["panel_tab"];

/**
 * One thing a profile may set.
 *
 * `describe` answers the same on every call with nothing run. `apply` runs when a session starts, with the values the profile holds
 * for the item already read against its schema; it must change nothing outside the effect it answers with.
 */
export const ProfileItem = described["profile_item"];

/**
 * A provider of secrets. One instance is one configuration of one provider. Every setting has a default, so a host can make an
 * instance with none to describe the provider before anyone has set it up.
 *
 * A provider that runs a program (a password manager's command) starts it through the `spawner` it is handed, which is the host's:
 * every program a provider runs starts through it, and the provider destroys it, even when it refuses. A script has no other way
 * to start one.
 *
 * A value is text. A provider that is asked something it cannot do answers `UNSUPPORTED` ([`unsupported`]); one that cannot be
 * reached or has not been unlocked answers `GONE` ([`unavailable`]) with a reason that holds no value, and the host asks
 * the person instead.
 */
export const SecretProvider = described["secret_provider"];

/**
 * A page of Settings, or a group on one.
 *
 * `describe` answers the same on every call with nothing run. `read` and `write` are asked only for a [`Stored::Provider`]
 * section; a [`Stored::Config`] section answers them with nothing.
 */
export const SettingsSection = described["settings_section"];

/** A provider of speech to text. One instance is one configuration of one provider. */
export const SpeechProvider = described["speech_provider"];

/**
 * One recording: audio goes in a chunk at a time, text comes out.
 *
 * A session's methods may be called from different threads, one at a time. Every session ends with [`finish`] or
 * [`cancel`], and dropping one is a cancel.
 *
 * [`finish`]: SpeechSession::finish
 * [`cancel`]: SpeechSession::cancel
 */
export const SpeechSession = described["speech_session"];

/** A provider of text to speech. One instance is one configuration of one provider. */
export const SpeechOutput = described["speech_output"];

/**
 * One utterance: audio comes out a chunk at a time, in order, while the provider is still speaking.
 *
 * A utterance's methods may be called from different threads. Every one ends with the audio read to its end, an error, or
 * [`stop`]; dropping one is a stop.
 *
 * [`stop`]: SpeechUtterance::stop
 */
export const SpeechUtterance = described["speech_utterance"];

/**
 * Knows one program: where its copies are, what is newest, and how to install it into a folder the host owns.
 *
 * Every method is synchronous and required, and answers for the store as configured. Every object a method is handed is
 * the store's from then on, and it destroys each, even when it refuses. `GUATIAO_ERR_UNSUPPORTED` always comes with the
 * reason.
 */
export const ProgramStore = described["program_store"];

/**
 * How an install tells the person what it is doing. The host implements it and hands one to
 * [`apply`](ProgramStore::apply); the store destroys it when the apply ends.
 *
 * When the person cancels, every call answers `GUATIAO_ERR_GONE` and `cancelled` is true.
 */
export const InstallPrompter = described["install_prompter"];

/**
 * What the host does for a store on the machine its spawner runs on: the checked fetch, the safe unpack and the look for
 * files. A store never opens a connection or writes a file by itself.
 */
export const InstallTools = described["install_tools"];

/** Adds types to the Store. The same answer on every call, with nothing run and no connection opened. */
export const StoreExtension = described["store_extension"];

/** Reads an agent's own quota. A provider is the same on every call; what it keeps for one agent is in the reading it opens. */
export const UsageReader = described["usage_reader"];

/** One agent's quota, read as often as the host asks. Its methods may be called from different threads, one at a time. */
export const UsageReading = described["usage_reading"];

/** The processes that belong to an agent, which the host finds from the operating system's process table. */
export const ProcessMembers = described["process_members"];

/**
 * Describes an agent, and answers what Canoa does for it beyond its description. `describe` is the same answer on every call, with
 * nothing run and no connection opened; every other method has a default that says the agent has nothing to add.
 */
export const AgentVendor = described["agent_vendor"];
